'use strict';
// Nose bridges belong on the facial axis; a crooked style bends within that placement.
window.RUN=async()=>{const {ok,exc,out}=Kit.report();try{const E=T.PortraitEngine,A=T.PortraitArtwork;await A.ready;const data=c=>c.getContext('2d').getImageData(0,0,c.width,c.height).data;let cases=0;
 for(const race of E.races)for(const profile of ['male','female'])for(const nose of E.partsFor(race,'nose'))for(const noseWidth of [-2,0,2]){const p=A.build({...E.startRace(race,E.startProfile(profile)),profile,nose,adjustments:{noseWidth},beard:'none',headwear:'none'},{size:128}),d=data(p.layers.nose),a=p.anchors;let top=128,bottom=-1;for(let y=0;y<128;y++)for(let x=0;x<128;x++)if(d[(y*128+x)*4+3]){top=Math.min(top,y);bottom=Math.max(bottom,y);}let center=0,rows=0;for(let y=top;y<Math.min(bottom,top+3);y++){let l=128,r=-1;for(let x=0;x<128;x++)if(d[(y*128+x)*4+3]){l=Math.min(l,x);r=Math.max(r,x);}if(r>=l){center+=(l+r+1)/2;rows++;}}if(!rows||Math.abs(center/rows-a.nose.x)>1||Math.abs(a.nose.x-a.mouth.x)>1)throw Error('Off-center bridge: '+race+'/'+profile+'/'+nose+'/'+noseWidth+' at '+center/rows+' versus '+a.nose.x);cases++;}
 ok(cases===E.races.reduce((n,r)=>n+E.partsFor(r,'nose').length*6,0),cases+' nose variants align with the face/mouth axis across races, profiles and nose-width extremes');
 const base={...E.startProfile('male'),headwear:'hood',beard:'moustache',mouth:'cupid',eyes:'upturned'},straight=A.build({...base,nose:'straight'}),crooked=A.build({...base,nose:'crooked'});ok(crooked.config.nose==='crooked'&&straight.layers.nose.toDataURL()!==crooked.layers.nose.toDataURL(),'crooked noses keep a distinct bend and their existing recipe identity');
 ok(E.order.filter(s=>s.id!=='nose').every(s=>straight.layers[s.id].toDataURL()===crooked.layers[s.id].toDataURL()),'nose changes preserve eyes, mouth, skin, hair, beard and equipment placement');
 const dwarf={...E.startRace('dwarf',E.startProfile('male')),profile:'male',beard:'none'};ok(A.build({...dwarf,nose:'dwarf-broken'}).layers.nose.toDataURL()!==A.build({...dwarf,nose:'dwarf-bulb'}).layers.nose.toDataURL(),'broken dwarf noses remain distinct after bridge centering');
 }catch(e){exc(e)}finally{out()}};
